function haversineKm(lat1, lon1, lat2, lon2) {
  const R = 6371.0;
  const toRad = d => (d * Math.PI) / 180.0;
  const p1 = toRad(lat1), p2 = toRad(lat2);
  const a = Math.sin(toRad(lat2 - lat1) / 2) ** 2 +
            Math.cos(p1) * Math.cos(p2) * Math.sin(toRad(lon2 - lon1) / 2) ** 2;
  return 2.0 * R * Math.atan2(Math.sqrt(a), Math.sqrt(1.0 - a));
}

function compassDirection(lat1, lon1, lat2, lon2) {
  const dy = lat2 - lat1;
  const dx = lon2 - lon1;
  const angle = ((Math.atan2(dx, dy) * 180) / Math.PI + 360) % 360;
  const dirs = ['N', 'NE', 'E', 'SE', 'S', 'SW', 'W', 'NW'];
  return dirs[Math.floor((angle + 22.5) / 45) % 8];
}

function buildSpatialGraphEdges() {
  const edges = [];
  for (let i = 0; i < UGANDA_DISTRICTS.length; i++) {
    for (let j = i + 1; j < UGANDA_DISTRICTS.length; j++) {
      const d = haversineKm(
        UGANDA_DISTRICTS[i].lat, UGANDA_DISTRICTS[i].lon,
        UGANDA_DISTRICTS[j].lat, UGANDA_DISTRICTS[j].lon
      );
      if (d <= DIST_THRESHOLD_KM) {
        edges.push({ u: i, v: j, distKm: d });
      }
    }
  }
  state.edgesList = edges;
}

function getNeighboursForDistrict(districtId) {
  const d0 = UGANDA_DISTRICTS[districtId];
  const list = [];
  for (const e of state.edgesList) {
    let nbId = -1;
    if (e.u === districtId) nbId = e.v;
    else if (e.v === districtId) nbId = e.u;
    if (nbId !== -1) {
      const nb = UGANDA_DISTRICTS[nbId];
      list.push({
        district: nb,
        distKm: e.distKm,
        direction: compassDirection(d0.lat, d0.lon, nb.lat, nb.lon)
      });
    }
  }
  list.sort((a, b) => a.distKm - b.distKm);
  return list;
}

