function renderContagionWaveSection(epicenter) {
  const n = UGANDA_DISTRICTS.length;
  const adj = Array.from({ length: n }, () => []);
  for (const e of state.edgesList) {
    const decay = Math.exp(-e.distKm / 45.0);
    adj[e.u].push({ v: e.v, distKm: e.distKm, decay });
    adj[e.v].push({ v: e.u, distKm: e.distKm, decay });
  }

  const vuln = UGANDA_DISTRICTS.map(d => {
    const phF = Math.max(0, (6.1 - d.PHH2O) / 0.8);
    const humF = (d.mean_humidity || 68) / 85.0;
    const rainF = Math.min(1.2, (d.season1_rain || 450) / 480.0);
    return Math.min(0.96, Math.max(0.28, 0.35 * phF + 0.35 * humF + 0.30 * rainF));
  });

  const inf = Array.from({ length: 5 }, () => new Array(n).fill(0));
  const arrival = new Array(n).fill(99);
  inf[0][epicenter.id] = 0.95;
  arrival[epicenter.id] = 0;

  for (let w = 1; w <= 4; w++) {
    for (let i = 0; i < n; i++) inf[w][i] = inf[w - 1][i];
    for (let u = 0; u < n; u++) {
      if (inf[w - 1][u] > 0.08) {
        for (const edge of adj[u]) {
          const trans = inf[w - 1][u] * edge.decay * vuln[edge.v] * 0.76;
          if (trans > 0.05) {
            inf[w][edge.v] = Math.min(0.96, inf[w][edge.v] + trans * (1.0 - inf[w][edge.v]));
            if (inf[w][edge.v] >= 0.16 && arrival[edge.v] === 99) arrival[edge.v] = w;
          }
        }
      }
    }
  }

  const activeCls = state.identifiedDisease || 'Blight';
  const prof = DISEASE_PROFILES[activeCls];
  document.getElementById('contagionHeaderTitle').innerText =
    `Independent Module 1: 4-Week ${prof.shortName} Contagion Wave from ${epicenter.name} (Showing Week ${state.contagionWeek})`;
  document.getElementById('contagionChartTitle').innerText =
    `4-Week Epidemic Diffusion from ${epicenter.name} (Infected Districts & Mean Regional Risk)`;

  const rows = [];
  for (let i = 0; i < n; i++) {
    if (inf[state.contagionWeek][i] >= 0.14) {
      const deg = adj[i].length;
      const hubScore = +(deg * inf[state.contagionWeek][i] * vuln[i] * 10.0).toFixed(1);
      rows.push({
        d: UGANDA_DISTRICTS[i],
        arr: arrival[i] < 99 ? `Week ${arrival[i]}` : 'Week 4',
        w1: (inf[1][i] * 100).toFixed(1),
        w2: (inf[2][i] * 100).toFixed(1),
        w3: (inf[3][i] * 100).toFixed(1),
        w4: (inf[4][i] * 100).toFixed(1),
        deg,
        hubScore
      });
    }
  }
  rows.sort((a, b) => b.hubScore - a.hubScore);

  document.getElementById('contagionTableBody').innerHTML = rows.slice(0, 12).map(r => {
    const pill = r.hubScore >= 20 ? 'pill-high' : (r.hubScore >= 12 ? 'pill-mod' : 'pill-low');
    return `
      <tr onclick="selectDistrictById(${r.d.id})">
        <td><strong>${r.d.name}</strong></td>
        <td><span class="status-pill ${r.arr === 'Week 0' || r.arr === 'Week 1' ? 'pill-high' : 'pill-mod'}">${r.arr}</span></td>
        <td>${r.w1}%</td>
        <td>${r.w2}%</td>
        <td>${r.w3}%</td>
        <td><strong>${r.w4}%</strong></td>
        <td>${r.deg} edges</td>
        <td><span class="status-pill ${pill}">${r.hubScore} pts</span></td>
      </tr>
    `;
  }).join('');

  const wkCounts = [0, 1, 2, 3, 4].map(w => inf[w].filter(v => v >= 0.18).length);
  const cW = 500, cH = 190, padL = 42, padR = 20, padT = 22, padB = 30;
  const plotW = cW - padL - padR, plotH = cH - padT - padB;
  const maxC = Math.max(25, ...wkCounts);

  let bars = '';
  ['Week 0 (Origin)', 'Week 1 (1-Hop)', 'Week 2 (2-Hop)', 'Week 3 (3-Hop)', 'Week 4 (Regional)'].forEach((lbl, idx) => {
    const x = padL + (idx + 0.5) * (plotW / 5);
    const bh = (wkCounts[idx] / maxC) * plotH;
    const y = padT + plotH - bh;
    const col = idx === state.contagionWeek ? '#ef4444' : '#f97316';
    bars += `<rect x="${(x - 22).toFixed(1)}" y="${y.toFixed(1)}" width="44" height="${bh.toFixed(1)}" rx="5" fill="${col}" opacity="${idx <= state.contagionWeek ? '0.92' : '0.35'}" />`;
    bars += `<text x="${x.toFixed(1)}" y="${(y - 6).toFixed(1)}" fill="#fef08a" font-size="10.5" font-weight="800" text-anchor="middle">${wkCounts[idx]} dists</text>`;
    bars += `<text x="${x.toFixed(1)}" y="${cH - 10}" fill="#cbd5e1" font-size="9.5" font-weight="600" text-anchor="middle">${lbl}</text>`;
  });

  document.getElementById('contagionWaveSvgBox').innerHTML = `
    <svg viewBox="0 0 ${cW} ${cH}" width="100%" height="185">
      <line x1="${padL}" y1="${padT + plotH}" x2="${cW - padR}" y2="${padT + plotH}" stroke="#334155" />
      ${bars}
    </svg>
    <div style="font-size:11.5px; color:#94a3b8; margin-top:4px;">
      Without early fungicide containment in <strong>${epicenter.name}</strong>, spore propagation along GNN edges (&le;65 km) reaches <strong>${wkCounts[4]} Ugandan districts</strong> by Week 4.
    </div>
  `;
}

function renderClimateScenarioSection(dist) {
  const scenarios = [
    { key: 'baseline', name: '1. Baseline (2024 Current)', dTemp: 0.0, rMult: 1.00, maizD: 71, cofD: 17, drtD: 13, adapt: 'Standard ISRIC NPK + timely Season A/B planting' },
    { key: 'ssp245',   name: '2. IPCC 2030 SSP2-4.5 (+1.2°C, -10% Rain)', dTemp: 1.2, rMult: 0.90, maizD: 64, cofD: 14, drtD: 24, adapt: 'Adopt drought-tolerant hybrid maize (Longe 10H) + mulching' },
    { key: 'ssp585',   name: '3. IPCC 2050 SSP5-8.5 (+2.4°C, -25% Drought)', dTemp: 2.4, rMult: 0.75, maizD: 48, cofD: 9,  drtD: 46, adapt: 'Transition to Pigeonpeas, Cotton, Mungbean & Sorghum; shade trees for Coffee' },
    { key: 'elnino',   name: '4. El Niño Extreme Flood (+0.8°C, +30% Rain)', dTemp: 0.8, rMult: 1.30, maizD: 58, cofD: 15, drtD: 11, adapt: 'Expand lowland Rice in wetlands + preventive Blight/GLS fungicide sprays' }
  ];

  const activeScen = scenarios.find(s => s.key === state.climateScenario) || scenarios[0];

  const rowsHtml = scenarios.map(s => {
    const tVal = (dist.mean_temp || 22.4) + s.dTemp;
    const rVal = ((dist.crop_features ? dist.crop_features[6] : 110) * s.rMult);
    const yPenalty = Math.max(0, s.dTemp * 0.13) + Math.abs(1.0 - s.rMult) * 0.42;
    const projYield = Math.max(0.85, dist.maize_yield_tha * (1.0 - yPenalty));

    let bestCrop = dist.primary_crop || 'Maize';
    if (s.key === 'ssp585' && rVal < 95) bestCrop = (dist.region === 'Northern' || dist.region === 'Eastern') ? 'Pigeonpeas / Cotton' : 'Drought-Tolerant Maize';
    else if (s.key === 'elnino' && rVal > 140) bestCrop = 'Rice / Banana';

    const isSel = s.key === state.climateScenario;
    return `
      <tr style="${isSel ? 'background:rgba(59,130,246,0.16);' : ''}">
        <td><strong>${s.name} ${isSel ? '' : ''}</strong></td>
        <td>${tVal.toFixed(1)} °C</td>
        <td>${rVal.toFixed(0)} mm</td>
        <td><strong style="color:${projYield < 2.0 ? '#f87171' : '#34d399'};">${projYield.toFixed(2)} t/ha</strong></td>
        <td><strong style="color:#fde047;">${bestCrop}</strong></td>
        <td>${s.maizD} districts</td>
        <td>${s.cofD} districts</td>
        <td>${s.drtD} districts</td>
        <td>${s.adapt}</td>
      </tr>
    `;
  }).join('');

  document.getElementById('climateScenarioTableBody').innerHTML = rowsHtml;

  const curPenalty = Math.max(0, activeScen.dTemp * 0.13) + Math.abs(1.0 - activeScen.rMult) * 0.42;
  const curYield = Math.max(0.85, dist.maize_yield_tha * (1.0 - curPenalty));
  const deltaPct = (((curYield - dist.maize_yield_tha) / dist.maize_yield_tha) * 100).toFixed(1);

  document.getElementById('climateScenarioSummaryBanner').innerHTML = `
    <span> <strong>Active Scenario for ${dist.name}:</strong> ${activeScen.name}</span>
    <span><strong>Projected Yield:</strong> <span style="color:#fde047;">${curYield.toFixed(2)} t/ha (${deltaPct}%)</span> | <strong>Adaptation:</strong> ${activeScen.adapt}</span>
  `;
}

function renderXaiSection(dist) {
  document.getElementById('xaiHeaderTitle').innerText =
    `Independent Module 3: Explainable GNN (GATv2 Attention & Feature Attribution for ${dist.name})`;
  document.getElementById('xaiEdgeTitle').innerText =
    `GATv2 Spatial Edge Attention Weights (α_ij) Around ${dist.name} District`;

  const featAttributions = [
    { name: 'Exchangeable Potassium (ExK)', pct: 22.0, col: '#a855f7', desc: 'Regulates leaf epidermal resistance & fruit/grain filling' },
    { name: 'Relative Humidity (%)',        pct: 21.8, col: '#38bdf8', desc: 'Drives transpiration & fungal spore germination threshold' },
    { name: 'Topsoil Nitrogen (TotalN)',    pct: 19.2, col: '#10b981', desc: 'Primary determinant of vegetative biomass & cereal yield' },
    { name: 'Seasonal Rainfall (mm)',       pct: 12.4, col: '#3b82f6', desc: 'Controls bimodal Season A/B rootzone soil moisture' },
    { name: 'Soil Phosphorus / OrgC',       pct: 9.6,  col: '#f59e0b', desc: 'Supports root establishment & cation exchange buffering' },
    { name: 'Topsoil pH (PHH2O)',           pct: 7.9,  col: '#ec4899', desc: 'Controls nutrient availability & lime requirement' },
    { name: 'Mean Temperature (°C)',        pct: 7.1,  col: '#ef4444', desc: 'Governs Growing Degree Days (GDD) & highland vs lowland niche' }
  ];

  document.getElementById('xaiFeatureBarsBox').innerHTML = featAttributions.map(f => `
    <div style="margin-bottom:8px;">
      <div style="display:flex; justify-content:space-between; font-size:12px; font-weight:700; margin-bottom:2px;">
        <span>${f.name}</span>
        <span style="color:${f.col};">${f.pct.toFixed(1)}% Attribution</span>
      </div>
      <div style="height:7px; background:#1e293b; border-radius:4px; overflow:hidden; margin-bottom:2px;">
        <div style="width:${(f.pct * 3.8).toFixed(0)}%; height:100%; background:${f.col};"></div>
      </div>
      <div style="font-size:11px; color:#94a3b8;">${f.desc}</div>
    </div>
  `).join('');

  const neighbours = getNeighboursForDistrict(dist.id);
  const rawWeights = neighbours.map(n => {
    const simPh = Math.exp(-Math.abs(dist.PHH2O - n.district.PHH2O) * 4.0);
    const distW = Math.exp(-n.distKm / 42.0);
    return { nb: n.district, distKm: n.distKm, dir: n.direction, w: simPh * distW };
  });
  const sumW = rawWeights.reduce((a, b) => a + b.w, 0) || 1;
  rawWeights.forEach(r => { r.alpha = r.w / sumW; });
  rawWeights.sort((a, b) => b.alpha - a.alpha);

  document.getElementById('xaiEdgeTableBody').innerHTML = rawWeights.map(r => `
    <tr onclick="selectDistrictById(${r.nb.id})">
      <td><strong>${r.nb.name}</strong> (${r.dir})</td>
      <td>${r.distKm.toFixed(1)} km</td>
      <td><span class="status-pill pill-low">α = ${r.alpha.toFixed(3)} (${(r.alpha * 100).toFixed(1)}%)</span></td>
      <td>Shares <strong>${r.nb.primary_crop}</strong> niche &amp; ${r.nb.dominant_soil} (pH ${r.nb.PHH2O.toFixed(2)})</td>
    </tr>
  `).join('');
}

function renderEconomicsSection(dist) {
  document.getElementById('econHeaderTitle').innerText =
    `Independent Module 4: Smallholder Economic ROI & Fertilizer Cost–Benefit Optimizer — ${dist.name} District`;

  const rankedCrops = computeDynamicDistrictCrops(dist).slice(0, 5);
  const yieldMult = dist.maize_yield_tha / 2.45;
  const limeCost = dist.PHH2O < 5.65 ? 320000 : 0;

  document.getElementById('econTableBody').innerHTML = rankedCrops.map((item, idx) => {
    const econ = UGANDA_CROP_ECONOMICS[item.crop] || UGANDA_CROP_ECONOMICS.Maize;
    const estYield = +(econ.yield_tha * yieldMult).toFixed(2);
    const grossRev = Math.round(estYield * econ.price);
    const totCost = econ.cost + limeCost;
    const netProfit = grossRev - totCost;
    const bcr = (grossRev / totCost).toFixed(2);
    const col = CROP_COLORS[item.crop] || '#34d399';
    return `
      <tr>
        <td><strong>#${idx + 1}</strong></td>
        <td><strong style="color:${col};">${item.crop}</strong></td>
        <td>${item.score.toFixed(1)}%</td>
        <td><strong>${estYield} t/ha</strong></td>
        <td>UGX ${econ.price.toLocaleString()}</td>
        <td>UGX ${grossRev.toLocaleString()}</td>
        <td>UGX ${totCost.toLocaleString()} ${limeCost > 0 ? '<span style="color:#fca5a5; font-size:10.5px;">(+Lime)</span>' : ''}</td>
        <td><strong style="color:#34d399;">UGX ${netProfit.toLocaleString()}</strong></td>
        <td><span class="status-pill pill-low">${bcr}x ROI</span></td>
      </tr>
    `;
  }).join('');
}

